schema_ddl.model_predictions_alter:
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema='ssq' AND table_name='model_predictions' AND column_name='data_date'
    ) THEN
        ALTER TABLE ssq.model_predictions ADD COLUMN data_date DATE;
        UPDATE ssq.model_predictions SET data_date = run_at::date WHERE data_date IS NULL;
        ALTER TABLE ssq.model_predictions ALTER COLUMN data_date SET DEFAULT CURRENT_DATE;
        ALTER TABLE ssq.model_predictions ALTER COLUMN data_date SET NOT NULL;
    END IF;
END $$;
CREATE INDEX IF NOT EXISTS ix_model_predictions_data_date ON ssq.model_predictions (data_date);

cleanup_design.dry_run_sql:
SELECT COUNT(*) AS will_delete
FROM ssq.model_predictions
WHERE data_date < CURRENT_DATE - INTERVAL '30 days';
